    REFERENCES demo.customers (id);
ALTER TABLE demo.shopping_cart_items
    ADD CONSTRAINT fk_cart_items_book FOREIGN KEY (book_id)
    REFERENCES demo.books (id);
ALTER TABLE demo.shopping_cart_items
